// n8n Cloud: Open-Meteo 天氣資訊。未連接的私人資料一律明確標示，禁止編造。
const parts = new Intl.DateTimeFormat('en-US', {timeZone:'Asia/Taipei', year:'numeric', month:'2-digit', day:'2-digit'}).formatToParts(new Date());
const pick = (key) => parts.find((x) => x.type === key)?.value;
const ymd = [pick('year'),pick('month'),pick('day')].join('-');
const weather = $input.first().json.daily || {};
const high = weather.temperature_2m_max?.[0];
const low = weather.temperature_2m_min?.[0];
const rain = weather.precipitation_probability_max?.[0];
const code = weather.weather_code?.[0];
const meaning = (n) => {
  if (n === 0) return '晴朗';
  if (n >= 1 && n <= 3) return '晴時多雲';
  if (n === 45 || n === 48) return '有霧';
  if ([51,53,55,56,57].includes(n)) return '毛毛雨';
  if ([61,63,65,66,67,80,81,82].includes(n)) return '有雨';
  if ([71,73,75,77,85,86].includes(n)) return '可能降雪';
  if ([95,96,99].includes(n)) return '有雷雨';
  return '天氣狀況未提供';
};
const valid = [high,low,rain].every((v) => typeof v === 'number' && Number.isFinite(v));
const weatherText = valid ? [
  '🌤 台北市今日天氣：' + meaning(code),
  '🌡 溫度：' + low + '～' + high + '°C',
  '☔ 最高降雨機率：' + rain + '%',
].join('\n') : '🌤 天氣資料暫時無法取得';
const text = [
  '☀️ 私人 LINE AI Agent｜每日早報',
  '📅 ' + ymd + '（台灣時間）',
  '',
  weatherText,
  '',
  '📆 今日行程：尚未連接個人行事曆',
  '✅ 今日待辦：尚未連接待辦資料',
  '🎯 建議：先確認今天最重要的一件事。',
  '',
  '天氣資料：Open-Meteo（預設台北市中心；預報僅供參考）',
].join('\n');
return [{ json: { id: 'morning-' + ymd, text } }];
